fn target_bush_v30(&self, player: &PlayerState, data: &OperationData) -> usize   // cover.rs:134~194

// --- 135: 담당 라인의 타워를 뽑는다 (AbstractGameWithCache::tower, simulation.rs:1822~1826 인라인)
//     tower(line, team) = match line { Top => top_tower, Mid => mid_tower, Bottom => bottom_tower }[team]
//                          .or( 같은 라인의 *_tower2[team] )        // Option::or, option.rs:1622
//     team >= 2 면 panic_bounds_check (bounds len 2)
let tower: Option<&Entity> = self.line 별 (1차타워[team]).or(2차타워[team]);

// --- 136~142: 그 라인 타워가 하나도 없으면 라인/팀만으로 즉시 결정
if tower.is_none() {                       // 136 (Option::is_none, option.rs:681-682)
    return match self.line {               // 137
        Top    => if team == 0 { 2 } else { 16 },   // 138
        Mid    => if team == 0 { 4 } else { 17 },   // 139
        Bottom => if team == 0 { 9 } else { 21 },   // 140
    };
}

// --- 144: 여기서부터 tower 는 Some. (unwrap 이 인라인되고 패닉 경로는 136 덕에 소거됨)
let tower = tower.unwrap();
// --- 145: 내 챔피언. player_champion[team][player.info.position.as_index()].unwrap()
//     None 이면 core::option::unwrap_failed 로 패닉
let champ: &Entity = data.cache.player_champion[team][pos].unwrap();

// 공통 술어(블록 36 에서 한 번 계산해 세 라인이 공유):
//   is_tower_variant = (tower.ty 판별자 == 2)                       // EntityType::Tower
//   is_second_tower  = (tower.ty.Tower.ty as u8 > 4)                // TowerType 5/6/7 = *2
//   is_tower2()      = is_tower_variant && is_second_tower          // entity.rs:1308-1309

match self.line {                          // 147

  // ============ Top (149~161) ============
  Top => {
    if let EntityType::Tower(info) = &tower.ty {          // 149  (판별자 != 2 면 160 의 unreachable!())
        if tower.ty.is_tower2() {                         // 150  (= TowerType > 4)
            if team == 0 { 3 } else { 6 }                 // 151
        } else {                                          // 152
            if info.nearest_enemy.is_some() {             // 153  (Tower+0x18 판별자 != 0)
                if team == 0 { 6 } else { 3 }             // 154  ★여기만 3/6 이 뒤집힌다
            } else {
                if team == 0 { 3 } else { 6 }             // 156
            }
        }
    } else { unreachable!() }                             // 160  (panic, col 11)
  }

  // ============ Mid (164~172) — 유일하게 좌표(맵 사이드)를 본다 ============
  Mid => {
    if tower.ty.is_tower2() {                             // 164
        // is_top_side(data.context, champ.x, champ.y)     // map_regions.rs:21~24
        //   ry = context.setting.height - champ.y ;  return ry < champ.x
        if !is_top_side(ctx, champ.x, champ.y) {          // 165 (IR 분기 극성이 반전 = 소스가 부정형)
            if team == 0 { 8 } else { 12 }                // 166
        } else {
            if team == 0 { 13 } else { 18 }               // 168
        }
    } else {
        // ★이 가지만 team 을 전혀 안 본다
        if is_top_side(ctx, champ.x, champ.y) { 14 } else { 11 }   // 171
    }
  }

  // ============ Bottom (179~191) — Top 과 완전 동형, 값만 15/20 ============
  Bottom => {
    if let EntityType::Tower(info) = &tower.ty {          // 179  (아니면 190 unreachable!())
        if tower.ty.is_tower2() {                         // 180
            if team == 0 { 15 } else { 20 }               // 181
        } else {
            if info.nearest_enemy.is_some() {             // 183
                if team == 0 { 20 } else { 15 }           // 184  ★뒤집힘
            } else {
                if team == 0 { 15 } else { 20 }           // 186
            }
        }
    } else { unreachable!() }                             // 190
  }
}                                                          // ret at 194

